pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the array length and a single amount and a recipient address
    // we use arrays constructed from the fuzzed params so the fuzzer can explore many inputs
    function testFuzz_property(uint8 len, uint256 v0, address to0) public {
        // keep len reasonable but allow zero handled by contract (it requires >0 so we need len>0)
        vm.assume(len > 0 && len <= 10);

        // construct arrays
        address[] memory tos = new address[](len);
        uint256[] memory vals = new uint256[](len);

        // fill with fuzzed values; use to0 and v0 repeated so fuzzer can vary them
        for (uint i = 0; i < len; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(to0, i)))));
            // ensure vals are within a range that avoids overflow in multiplication v * 1e18
            // but do not overconstrain: bound it to uint256 max / 1e18
            uint256 maxSafe = type(uint256).max / 1000000000000000000;
            uint256 vv = v0;
            if (vv > maxSafe) vv = vv % (maxSafe + 1);
            vals[i] = vv;
        }

        // call transfer and capture whether it completes (does not revert) and the return value if it does
        bool ok;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // GENERAL PROPERTY: If call completes (ok == true) then it must return true on the reference contract.
        // The mutant that returns false will break this property for some inputs; this single assert enforces it.
        assertTrue(!ok || ret);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz an array length (as uint8 to keep test cheap), one uint256 amount, and one address recipient.
    // The general rule: for any admissible inputs where transfer does not revert, it must return true.
    // The mutant returns false instead for completing calls. We observe the returned boolean via a try/catch.
    function testFuzz_property(uint8 len, uint256 amount, address to) public {
        // keep length reasonable but wide (0 is excluded by contract requirement, so we allow >0)
        uint256 l = bound(len, 0, 10); // small max to limit gas; allow 0..10
        vm.assume(l > 0); // admissible domain requires _tos.length > 0

        // build arrays
        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = to; // allow same addr repeated; fuzz supplies `to`
            // ensure amount satisfies the contract's multiplicative check:
            // require(v[i]==0 || ((v[i]*1e18)/v[i])==1e18)
            // Choose either 0 or a value that won't overflow when multiplied: pick amount itself if nonzero
            // but guard against values that break the identity due to overflow: restrict amount to 1..2**238
            uint256 safeAmount = amount;
            if (safeAmount != 0) {
                safeAmount = bound(uint256(safeAmount), 1, type(uint256).max / 1000000000000000000);
            }
            vals[i] = safeAmount;
        }

        // Call transfer and capture its boolean return via try/catch. We do not expect revert for admissible inputs,
        // but we must handle both cases. The universal property: if it completes, the returned bool must be true.
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, we consider the property vacuously true for this input domain, but we must still assert
            // the reference's rule only applies when it completes; so set ok=true to avoid failing the test for reverts.
            ok = true;
        }

        // Single assertion: the reference should always return true for completing calls; the mutant will cause
        // some completing calls to return false, causing this assertion to fail on the mutant.
        assertTrue(ok);
    }
}
